import { defineCollection } from 'astro:content';
import { file } from 'astro/loaders';
import { z } from 'astro/zod';

// Generated by scripts/import_comics.py from a CLZ Comics export.
const comics = defineCollection({
  loader: file('src/data/comics.json'),
  schema: z.object({
    title: z.string().min(1),
    publisher: z.string(),
    format: z.string(),
    size: z.enum(['omnibus', 'absolute', 'deluxe', 'hardcover', 'trade']),
    status: z.enum(['shelf', 'ordered', 'read', 'wishlist']),
    pages: z.number().int().positive().nullable(),
    year: z.number().int().nullable(),
    note: z.string(),
    coverUrl: z.url().nullable().optional(),
    cover: z.string().startsWith('/covers/').optional(),
    coverColor: z.string().regex(/^#[0-9a-f]{6}$/i).optional(),
    coverRatio: z.number().min(0.4).max(1.2).optional(),
  }),
});

export const collections = { comics };
